# ReentrantReadWriteLock读写锁

读写锁的目的是为了让读 — 读之间不加锁

| 冲突    | 策略   |
| ------- | ------ |
| 读 — 读 | 并行化 |
| 读 — 写 | 串行化 |
| 写 — 读 | 串行化 |
| 写 — 写 | 串行化 |

```java
package _05_AQS;

import java.util.*;

/**
 * @Author: youthlql-吕
 * @Date: 2019/9/26 10:58
 * <p>
 * 功能描述:
 */
public class Video34 {

    private static final ReentrantReadWriteLock lock = new ReentrantReadWriteLock(true);

    private static final Lock readLock = lock.readLock();
    private static final Lock writeLock = lock.writeLock();

    private static final List<String> data = new ArrayList<>();

    public static void main(String[] args) throws InterruptedException {
        new Thread(()->write(),"write-1").start();

        Thread.sleep(1000);
        new Thread(()->read(),"read-1").start();

        new Thread(()->read(),"read-2").start();

    }

    public static void write(){
        try{
            writeLock.lock();
            data.add("数据XXX");
            Thread.sleep(3000);
        } catch (InterruptedException e) {
            e.printStackTrace();
        } finally {
            System.out.println("写锁释放");
            writeLock.unlock();
        }
    }

    public static void read(){
        try{
            readLock.lock();
            for (String datum : data) {
                System.out.println(Thread.currentThread().getName() + " 读入："+datum);
            }
            Thread.sleep(3000);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            System.out.println("读锁释放");
            readLock.unlock();
        }
    }
}

